#!/usr/bin/env node
/**
 * Bakes the design system's stylesheets into app/src/styles.js.
 *
 * A Worker has no filesystem at runtime, so the CSS the generated pages carry
 * inline has to be part of the bundle. Generating it keeps tokens.css the one
 * place a colour is defined, rather than a second copy drifting inside the
 * application.
 *
 *   node app/tools/bundle-styles.js
 *
 * Runs automatically before dev and deploy; CI checks the committed file is
 * in step with the source.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.join(HERE, '..', '..');
const DS = path.join(REPO, 'design-system');
const OUT = path.join(HERE, '..', 'src', 'styles.js');

const SHEETS = ['tokens/tokens.css', 'css/base.css', 'css/components.css', 'css/web.css'];

const css = SHEETS
  .map(f => `/* ===== ${f} ===== */\n${fs.readFileSync(path.join(DS, f), 'utf8')}`)
  .join('\n\n');

// A backtick or ${ in the CSS would end the template literal early.
const escaped = css.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');

const banner = `/* Generated by app/tools/bundle-styles.js — do not edit.
 * Source: ${SHEETS.map(s => 'design-system/' + s).join(', ')}
 * Re-run after changing any of them. */\n\n`;

fs.writeFileSync(OUT, `${banner}export const STYLESHEET = \`${escaped}\`;\n`);

const check = process.argv.includes('--check');
if (check) {
  // Used by CI: a stale bundle means delivered pages carry the old colours.
  const committed = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (committed !== `${banner}export const STYLESHEET = \`${escaped}\`;\n`) {
    console.error('app/src/styles.js is out of date — run: node app/tools/bundle-styles.js');
    process.exit(1);
  }
}

console.log(`Wrote ${path.relative(REPO, OUT)} — ${(css.length / 1024).toFixed(0)}KB of CSS.`);
